const r = await api.get("/customers");
const items = r.items || [];
let nov = 0, unknown = 0;
for (const c of items) {
  const d = c.birth_date;
  if (!d) { unknown++; continue; }
  const m = d.match(/^\d{4}-(\d{2})/) || d.match(/(\d{1,2})월/) || d.match(/^\d{2}\/(\d{2})/);
  if (m && parseInt(m[1], 10) === 11) nov++;
  else if (!m) unknown++;
}
return { total: items.length, count: r.count, november: nov, unparsed: unknown, sampleFormat: items.slice(0,3).map(c => c.birth_date) };

